<script setup lang="ts">
import { computed, ref } from 'vue'
import { terms, lessons } from '../data/content'
import { normalizeSearch } from '../lib/search'
import { useLearning } from '../stores/learning'
import AppIcon from '../components/AppIcon.vue'
const query=ref(''),onlyFavorites=ref(false),store=useLearning()
const shown=computed(()=>terms.filter(t=>(!onlyFavorites.value || store.state.favorites.includes(t.id)) && normalizeSearch(`${t.arabic} ${t.transliteration} ${t.meaning}`).includes(normalizeSearch(query.value))))
function sourceFor(id:string){return lessons.find(l=>l.terms.some(t=>t.id===id))?.sumber || []}
</script>
<template><div class="page-heading"><div><p class="eyebrow">KENALI KATA, PAHAMI MAKNA</p><h1>Kamus istilah</h1><p>Teman kecil untuk istilah yang baru kamu temui.</p></div></div><div class="search-row"><div class="search-box"><AppIcon name="search" :size="18"/><label for="term-search" class="sr-only">Cari istilah Arab, transliterasi, atau arti</label><input id="term-search" v-model="query" placeholder="Cari istilah Arab, transliterasi, atau arti…" type="search"/></div><button class="filter-chip" :class="{selected:onlyFavorites}" :aria-pressed="onlyFavorites" @click="onlyFavorites=!onlyFavorites"><AppIcon name="star" :size="15"/>Favorit · {{store.state.favorites.length}}</button></div><p class="result-count" role="status">{{shown.length}} istilah ditemukan</p><div class="glossary-grid"><article v-for="term in shown" :key="term.id" class="card term-card"><div class="section-header"><span class="arabic term-arabic" lang="ar" dir="rtl">{{term.arabic}}</span><button class="icon-button favorite-button" :class="{'is-favorite':store.state.favorites.includes(term.id)}" :aria-pressed="store.state.favorites.includes(term.id)" :aria-label="`${store.state.favorites.includes(term.id)?'Hapus dari':'Tambahkan ke'} favorit: ${term.transliteration}`" @click="store.toggleFavorite(term.id)"><AppIcon name="star" :size="20"/></button></div><h2>{{term.transliteration}}</h2><p>{{term.meaning}}</p><div class="term-source"><span class="badge review">Perlu ditinjau</span><a v-for="source in sourceFor(term.id).filter(s=>term.sourceIds.includes(s.id))" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title}} ↗</a></div></article></div><section v-if="!shown.length" class="card empty-state"><AppIcon name="search" :size="28"/><h2>Belum ada istilah yang cocok</h2><p class="muted">Coba kata yang lebih singkat, atau lihat semua istilah.</p><button class="button secondary" @click="query='';onlyFavorites=false">Lihat semua istilah</button></section></template>
